import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void batch_norm_kernel(
    const half* input,
    half* output,
    const half* weight,
    const half* bias,
    const half* running_mean,
    const half* running_var,
    const float eps,
    const int batch_size,
    const int num_features,
    const int spatial_size
) {
    // Each thread handles one element in the batch
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= batch_size * num_features * spatial_size) return;

    // Calculate which batch, feature, and spatial position this thread handles
    int batch_idx = idx / (num_features * spatial_size);
    int remaining = idx % (num_features * spatial_size);
    int feature_idx = remaining / spatial_size;
    int spatial_idx = remaining % spatial_size;

    // Get input value
    half x = input[idx];

    // Get statistics for this feature
    half mean_val = running_mean[feature_idx];
    half var_val = running_var[feature_idx];

    // Normalize
    half normalized = __hsub(x, mean_val);
    half std = __hsqrt(__hadd(var_val, __float2half(eps)));
    normalized = __hdiv(normalized, std);

    // Scale and shift
    half result = __hfma(normalized, weight[feature_idx], bias[feature_idx]);

    output[idx] = result;
}

// Host wrapper function
extern "C" void launch_batch_norm(
    const half* input,
    half* output,
    const half* weight,
    const half* bias,
    const half* running_mean,
    const half* running_var,
    const float eps,
    const int batch_size,
    const int num_features,
    const int spatial_size
) {
    const int threads_per_block = 256;
    const int blocks = (batch_size * num_features * spatial_size + threads_per_block - 1) / threads_per_block;

    batch_norm_kernel<<<blocks, threads_per_block>>>(
        input, output, weight, bias, running_mean, running_var, eps,
        batch_size, num_features, spatial_size
    );

    cudaDeviceSynchronize();
}
"""

# Compile and load the CUDA extension
batch_norm_ext = load_inline(
    name="batch_norm_ext",
    cpp_sources="",
    cuda_sources=cuda_source,
    functions=["launch_batch_norm"],
    verbose=True
)

class ModelNew(torch.nn.Module):
    """
    Simple model that performs Batch Normalization using custom CUDA kernel.
    """
    def __init__(self, num_features: int):
        """
        Initializes the BatchNorm layer.

        Args:
            num_features (int): Number of features in the input tensor.
        """
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.weight = torch.nn.Parameter(torch.ones(num_features, dtype=torch.float16))
        self.bias = torch.nn.Parameter(torch.zeros(num_features, dtype=torch.float16))
        self.register_buffer('running_mean', torch.zeros(num_features, dtype=torch.float16))
        self.register_buffer('running_var', torch.ones(num_features, dtype=torch.float16))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Batch Normalization to the input tensor using custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, num_features, *).

        Returns:
            torch.Tensor: Output tensor with Batch Normalization applied, same shape as input.
        """
        # Ensure input is contiguous for memory access patterns
        x = x.contiguous()

        # Prepare output tensor
        output = torch.empty_like(x, dtype=torch.float16)

        # Call the CUDA kernel
        batch_norm_ext.launch_batch_norm(
            x.data_ptr(),
            output.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            self.running_mean.data_ptr(),
            self.running_var.data_ptr(),
            self.eps,
            x.shape[0],
            self.num_features,
            x.shape[2] * x.shape[3]
        )

        return output

